import pandas as pd
import numpy as np

# Load the datasets
crime_df = pd.read_csv(DATASET_PATH)
adj_df = pd.read_csv(ADJACENCY_PATH)

# Crime values indexed by borough
crime_values = crime_df.set_index('borough')['Crime_value']

# Build an undirected adjacency dictionary
neighbors = {borough: set() for borough in crime_values.index}
for _, row in adj_df.iterrows():
    b = row['borough']
    n = row['neighbor']
    if b in neighbors and n in neighbors:
        neighbors[b].add(n)
        neighbors[n].add(b)

# Iterative-R outlier detection
active = set(crime_values.index)
outlier_R = {}          # Stores R at the moment a borough is removed
threshold = 2.5
last_R = {}

while True:
    # Compute spatial differences using only currently active neighbors
    diffs = {}
    for b in active:
        nbrs = [n for n in neighbors[b] if n in active]
        if len(nbrs) == 0:
            diffs[b] = np.nan
        else:
            diffs[b] = crime_values.loc[b] - crime_values.loc[nbrs].mean()

    # Keep only boroughs that have at least one active neighbor
    valid_diffs = {b: d for b, d in diffs.items() if not np.isnan(d)}
    if len(valid_diffs) <= 1:
        break

    diff_array = np.array(list(valid_diffs.values()))
    mean_d = np.mean(diff_array)
    std_d = np.std(diff_array, ddof=1)
    if std_d == 0:
        break

    # Standardized R values
    R = {b: (d - mean_d) / std_d for b, d in valid_diffs.items()}
    last_R = R

    # Identify the most extreme borough
    extreme_borough = max(R, key=lambda k: abs(R[k]))
    if abs(R[extreme_borough]) > threshold:
        outlier_R[extreme_borough] = R[extreme_borough]
        active.remove(extreme_borough)
    else:
        break

# Determine Westminster's final statistic and classification
westminster = 'Westminster'
if westminster in outlier_R:
    stat = outlier_R[westminster]
    label = 'OUTLIER - HIGH' if stat > 0 else 'OUTLIER - LOW'
else:
    stat = last_R.get(westminster, np.nan)
    if abs(stat) > threshold:
        label = 'OUTLIER - HIGH' if stat > 0 else 'OUTLIER - LOW'
    else:
        label = 'NOT AN OUTLIER'

print(f"FINAL ANSWER: {label} (R = {stat:.4f})")
